//! 🎟️ The original caller incrementally admits numerical metadata before the exact job authority birth.
use super::*;
use semio_framework_job::{OriginalConstructionDemand,OriginalSourceBinding};
use semio_framework_value::{RetainedCloneStep,ValueRefusalKind};
use semio_framework_value::retained_clone::RetainedCloneClose;
use std::mem::{ManuallyDrop,size_of};
/// 🧳️ Original model and configuration owners remain retained through census, refusal and cancellation.
pub struct EnergyJobAdmission{source:OriginalSourceBinding,operation:Operation,bounds:EnergyNumericalBounds,model:ManuallyDrop<Option<Model>>,config:ManuallyDrop<Option<SimulationConfig>>,observer:wire::EnergyNumericalCensusCursor,census:Option<EnergyNumericalCensus>,rejection:Option<EnergyNumericalDimension>,job:ManuallyDrop<Option<EnergyJob>>,retirement:RetainedCloneClose,closing:bool}
impl EnergyJobAdmission{
 pub fn birth_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()+size_of::<Model>()+size_of::<SimulationConfig>(),depth:1,..Default::default()}}
 /// 🫴️ Moves both original input headers only when their unchanged caller funds the complete transfer.
 pub fn begin(operation:Operation,bounds:EnergyNumericalBounds,model:&mut Option<Model>,config:&mut Option<SimulationConfig>,output:&mut Option<Self>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if output.is_some()||model.is_none()||config.is_none(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy admission requires empty output and both original inputs").into())}if operation.operation!=cx.operation()||operation.generation!=cx.generation(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy admission requires its original operation and generation").into())}if cx.should_yield()||cx.is_cancelled(){return Ok(false)}let source=OriginalSourceBinding::borrow(cx);let d=Self::birth_demand();let mut admitted=false;semio_framework_job::close_original_retained_step(cx,d,|_|{*output=Some(Self{source,operation,bounds,model:ManuallyDrop::new(model.take()),config:ManuallyDrop::new(config.take()),observer:Default::default(),census:None,rejection:None,job:ManuallyDrop::new(None),retirement:Default::default(),closing:false});admitted=true;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(admitted)
 }
 fn validate(&self,cx:&StepContext<'_>)->Result<(),ValueError>{if self.source.matches(cx){Ok(())}else{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy admission requires the same original source and clock"))}}
 pub fn rejection(&self)->Option<EnergyNumericalDimension>{self.rejection}
 pub fn ready(&self)->bool{self.job.is_some()&&!self.closing}
 pub fn demands(&self)->Result<RetirementDemand,ValueError>{if self.closing{return self.close_demands()}if self.ready()||self.rejection.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<EnergyJob>>(),depth:1,..Default::default()})}if !self.observer.complete(){return Ok(self.observer.demand())}if self.census.is_none(){return Ok(RetirementDemand{copy_bytes:size_of::<EnergyNumericalCensus>(),depth:1,..Default::default()})}Ok(RetirementDemand{copy_bytes:size_of::<EnergyJobAuthority>()+size_of::<Model>()+size_of::<SimulationConfig>(),capacity_bytes:size_of::<EnergyJobAuthority>(),depth:1,..Default::default()})}
 /// 🔎️ Visits one bounded original metadata row, then separately admits the actual authority allocation.
 pub fn step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;if self.closing||cx.should_yield()||cx.is_cancelled(){return Ok(false)}if self.ready()||self.rejection.is_some(){return Ok(true)}let d=self.demands()?;
  if !self.observer.complete(){semio_framework_job::close_original_retained_step(cx,d,|g|Ok(RetainedCloneStep::Progress(self.observer.advance(self.model.as_ref().unwrap(),self.config.as_ref().unwrap(),g))))?;return Ok(false)}
  if self.census.is_none(){semio_framework_job::close_original_retained_step(cx,d,|_|{match self.observer.census(){Some(census)=>{self.rejection=census.first_exceeded(self.bounds.0);self.census=Some(census);},None=>{self.census=Some(Default::default());self.rejection=Some(EnergyNumericalDimension::ArithmeticOverflow);}}Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(self.rejection.is_some())}
  let mut admitted=None;semio_framework_job::admit_original_construction(cx,&mut admitted,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|_|{let capacity=match EnergyJob::from_observed(self.operation,self.model.take().unwrap(),self.config.take().unwrap(),self.census.unwrap()){Ok(job)=>{*self.job=Some(job);d.capacity_bytes},Err(rejected)=>{*self.model=Some(rejected.model);*self.config=Some(rejected.config);self.rejection=Some(rejected.dimension);0}};Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:capacity,..Default::default()}))})?;Ok(self.ready()||self.rejection.is_some())
 }
 /// 📤️ The admitted job moves once into the same original caller's retained slot.
 pub fn take(&mut self,output:&mut Option<EnergyJob>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if output.is_some(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy admitted job output slot is occupied").into())}if !self.ready()||cx.is_cancelled()||cx.should_yield(){return Ok(false)}let d=RetirementDemand{copy_bytes:size_of::<Option<EnergyJob>>(),depth:1,..Default::default()};let mut moved=false;semio_framework_job::close_original_retained_step(cx,d,|_|{*output=self.job.take();self.closing=true;moved=true;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(moved)}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if let Some(job)=self.job.as_ref(){return if job.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<EnergyJob>>(),depth:1,..Default::default()})}else{job.original_close_demands()}}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<Model>(false,&None,4096)}if self.model.is_some(){return self.retirement.next_owner_demands::<Model>(true,&None,4096)}if self.config.is_some(){return self.retirement.next_owner_demands::<SimulationConfig>(true,&None,4096)}Ok(Default::default())}
 /// ♻️ Every partial census and born job keeps its original caller through exact paid retirement.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{self.validate(cx)?;self.begin_close();if let Some(job)=self.job.as_mut(){if !job.terminal_is_empty(){return job.close_step(cx)}let d=RetirementDemand{copy_bytes:size_of::<Option<EnergyJob>>(),depth:1,..Default::default()};return semio_framework_job::close_original_retained_step(cx,d,|_|{drop(self.job.take());Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})}if self.terminal_is_empty(){return Ok(energy_done())}let d=self.close_demands()?;semio_framework_job::close_original_retained_step(cx,d,|g|{let step=if !self.retirement.is_empty(){self.retirement.step_granted(g)?}else if self.model.is_some(){self.retirement.begin_granted(&mut self.model,g)?.unwrap()}else{self.retirement.begin_granted(&mut self.config,g)?.unwrap()};Ok(RetainedCloneStep::Progress(step.progress()))})}
 pub fn terminal_is_empty(&self)->bool{self.model.is_none()&&self.config.is_none()&&self.job.is_none()&&self.retirement.is_empty()}
}
impl Drop for EnergyJobAdmission{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Energy admission abandoned its original model, configuration or job");}}

